    document.getElementById('mhsSubForm').onsubmit=async e=>{e.preventDefault();const {error}=await sb.from('subjects').insert({name:mhsSubName.value.trim(),code:mhsSubCode.value.trim()||null,status:true});if(error)return msg(error.message,true);await window.MHS_EXTRA.subjects();msg('Subject added.');};
    app.querySelectorAll('[data-sub-toggle]').forEach(b=>b.onclick=async()=>{const {error}=await sb.from('subjects').update({status:b.dataset.status==='true'}).eq('id',b.dataset.sub);if(error)return msg(error.message,true);await window.MHS_EXTRA.subjects();});
    app.querySelectorAll('[data-save-class]').forEach(b=>b.onclick=async()=>{try{const cls=b.dataset.saveClass;const checked=[...app.querySelectorAll('[data-cl="'+cls+'"]:checked')];const existing=links.filter(l=>l.class_id===cls&&l.academic_year_id===active.id);for(const l of existing){if(!checked.some(x=>x.dataset.sub===l.subject_id)){const {error}=await sb.from('class_subjects').delete().eq('id',l.id);if(error)throw error;}}for(const box of checked){const subject=box.dataset.sub;if(existing.some(l=>l.subject_id===subject))continue;const req=app.querySelector('[data-required="'+cls+'-'+subject+'"]').value==='true';const {error}=await sb.from('class_subjects').insert({academic_year_id:active.id,class_id:cls,subject_id:subject,is_compulsory:req});if(error)throw error;}await window.MHS_EXTRA.subjects();msg('Class subject structure saved.');}catch(e){msg(e.message,true);}});
